        return 1
    return count_paths(m - 1, n) + count_paths(m, n - 1)

The function below classifies a triangle given three side lengths using a deeply nested if/elif chain that is hard to read. Refactor it using clearer guard-clause / early-return structure so it produces IDENTICAL results (return 'invalid' if the sides cannot form a triangle, 'equilateral' if all sides equal, 'isosceles' if exactly two sides equal, otherwise 'scalene'). Return the complete refactored function, named exactly `classify_triangle`.

def classify_triangle(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        return 'invalid'
    else:
        if a + b <= c or a + c <= b or b + c <= a:
            return 'invalid'
        else:
            if a == b:
                if b == c:
                    return 'equilateral'
                else:
                    return 'isosceles'
            else:
                if b == c or a == c:
                    return 'isosceles'
                else:
                    return 'scalene'

